import json
from pathlib import Path
p=Path('output/geology-drill-demo'); d=json.loads((p/'zk0003-data.json').read_text(encoding='utf-8')); blob=json.dumps(d,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')
page=r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ZK0003 附表</title><style>body{margin:0;color:#263842;background:#f4f7f8;font:14px/1.5 "Microsoft YaHei",system-ui,sans-serif}header{background:white;border-bottom:1px solid #d5dee4;padding:16px 22px;position:sticky;top:0}h1{font-size:20px;margin:0 0 8px}.tabs{display:flex;gap:8px;margin-top:12px}button,a{padding:7px 12px;border:1px solid #c5d1d8;border-radius:6px;background:white;color:#176f76;text-decoration:none;cursor:pointer;font:inherit}.wrap{padding:14px 20px;overflow:auto}table{border-collapse:collapse;background:white;min-width:760px;width:100%}th,td{border:1px solid #d7e0e5;padding:6px 8px;text-align:left;vertical-align:top}th{background:#eaf0f2;position:sticky;top:112px}td.desc{max-width:550px;white-space:pre-wrap}.note{color:#61717e;font-size:12px}</style><header><h1>ZK0003 底稿附表</h1><span class="note">原始深度按底稿未校正值；派生长度与采取率标为计算值。此页不补缺失品位或岩性代码。</span><div class="tabs"><button onclick="show('layers')">分层（23）</button><button onclick="show('turns')">回次（131）</button><button onclick="show('samples')">样品（97）</button><button onclick="show('structures')">孔径记录点</button><a href="index.html">返回示图</a></div></header><main class="wrap" id="root"></main><script id="data" type="application/json">DATA_SLOT</script><script>const d=JSON.parse(document.getElementById('data').textContent),root=document.getElementById('root');function e(x){return String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function n(x){return typeof x==='number'?x.toFixed(2):e(x)}function table(title,heads,rows){root.innerHTML='<h2>'+title+'</h2><table><thead><tr>'+heads.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map((x,i)=>'<td class="'+(i===r.length-1?'desc':'')+'">'+e(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table>'}function show(k){if(k==='layers')table('分层', ['层号','顶深 m','底深 m','段长 m（计算）','岩心长 m','采取率 %（计算）','岩性代码','原始描述'],d.layers.map(x=>[x.id,n(x.top_m),n(x.bottom_m),n(x.thickness_m),n(x.core_m),n(x.recovery_percent.value),x.material_code,x.description]));if(k==='turns')table('回次',['回次号','顶深 m','底深 m','进尺 m','岩心长 m','采取率 %'],d.turns.map(x=>[x.id,n(x.top_m),n(x.bottom_m),n(x.advance_m),n(x.core_m),n(x.recovery_percent)]));if(k==='samples')table('样品',['样号','顶深 m','底深 m','样长 m（计算）','芯长 m（I列）','采取率 %（计算）'],d.samples.map(x=>[x.id,n(x.top_m),n(x.bottom_m),n(x.length_m),n(x.core_m),n(x.recovery_percent.value)]));if(k==='structures')table('孔径结构记录点',['深度 m','孔径 mm','说明'],d.structures.map(x=>[n(x.depth_m),n(x.diameter_mm),'仅为原表记录点，不代表全孔孔径']))}show('layers');</script></main></html>'''.replace('DATA_SLOT',blob)
(p/'drawing-data.html').write_text(page,encoding='utf-8')
